import { generatePagination } from "../utils/generatePagination"
import { clsx } from "clsx"
import { ArrowLeftIcon, ArrowRightIcon } from "@heroicons/react/24/outline"

export default function Pagination({
  totalPages,
  entriesPerPage,
  totalEntries,
  currentPage,
  onPageChange,
  onPageSizeChange,
}) {
  const startIndex = (currentPage - 1) * entriesPerPage + 1
  const endIndex = Math.min(startIndex + entriesPerPage - 1, totalEntries)

  const handleEntriesPerPageChange = event => {
    const newPageSize = Number(event.target.value)
    if (onPageSizeChange) {
      onPageSizeChange(newPageSize)
    }
  }

  const goToPage = pageNumber => {
    if (pageNumber < 1 || pageNumber > totalPages) return
    if (onPageChange) {
      onPageChange(pageNumber)
    }
  }

  const allPages = generatePagination(currentPage, totalPages)

  return (
    <div className="flex flex-col items-center justify-center sm:justify-between border-t border-gray-200 bg-white-50 px-4 py-3 sm:px-6">
      <div className="flex items-center justify-between w-full">
        <p className="text-sm text-gray-700 hidden sm:block">
          Showing <span className="font-medium">{startIndex}</span> to{" "}
          <span className="font-medium">{endIndex}</span> of{" "}
          <span className="font-medium">{totalEntries}</span> entries
        </p>
        <div className="flex items-center">
          <label htmlFor="entriesPerPage" className="mr-2 text-sm text-gray-700">
            Entries per page:
          </label>
          <select
            id="entriesPerPage"
            value={entriesPerPage}
            onChange={handleEntriesPerPageChange}
            className="border-gray-300 rounded-md text-sm"
          >
            <option value={3}>3</option>
            <option value={10}>10</option>
            <option value={25}>25</option>
            <option value={30}>30</option>
          </select>
        </div>

        <div className="inline-flex">
          <PaginationArrow
            direction="left"
            onClick={() => goToPage(currentPage - 1)}
            isDisabled={currentPage <= 1}
          />

          <div className="flex -space-x-px">
            {allPages.map((page, index) => {
              let position

              if (index === 0) position = "first"
              if (index === allPages.length - 1) position = "last"
              if (allPages.length === 1) position = "single"
              if (page === "...") position = "middle"

              return (
                <PaginationNumber
                  key={index}
                  page={page}
                  position={position}
                  isActive={currentPage === page}
                  onClick={() => typeof page === "number" && goToPage(page)}
                />
              )
            })}
          </div>

          <PaginationArrow
            direction="right"
            onClick={() => goToPage(currentPage + 1)}
            isDisabled={currentPage >= totalPages}
          />
        </div>
      </div>
    </div>
  )
}

function PaginationArrow({ direction, isDisabled, onClick }) {
  const className = clsx("flex h-10 w-10 items-center justify-center rounded-md border", {
    "pointer-events-none text-gray-300": isDisabled,
    "hover:bg-gray-100 cursor-pointer": !isDisabled,
    "mr-2 md:mr-4": direction === "left",
    "ml-2 md:ml-4": direction === "right",
  })

  const icon =
    direction === "left" ? <ArrowLeftIcon className="w-4" /> : <ArrowRightIcon className="w-4" />

  if (isDisabled) {
    return <div className={className}>{icon}</div>
  }

  return (
    <button type="button" className={className} onClick={onClick}>
      {icon}
    </button>
  )
}

function PaginationNumber({ page, isActive, position, onClick }) {
  const className = clsx("flex h-10 w-10 items-center justify-center font-normal text-sm border", {
    "rounded-l-md": position === "first" || position === "single",
    "rounded-r-md": position === "last" || position === "single",
    "z-10 bg-blue-600 text-white": isActive,
    "hover:bg-gray-100 cursor-pointer": !isActive && position !== "middle",
    "text-gray-300": position === "middle",
  })

  if (isActive || position === "middle") {
    return <div className={className}>{page}</div>
  }

  return (
    <button type="button" className={className} onClick={onClick}>
      {page}
    </button>
  )
}
