import React, { useState, useEffect } from "react"
import Header from "../layout/Header"
import Sidebar from "../layout/Sidebar"
import axios from "axios"
import Loader from "../components/Loader"
import Error from "../components/Error"
import { DateRangePicker } from "rsuite"
// import Pagination from "../components/pagination2"
import Pagination from "../components/Pagination"
import Papa from "papaparse"
import { Download, MoreHorizontal, X, ChevronDown, ChevronRight, RotateCcw } from "lucide-react"
import dayjs from "dayjs"
import { NumericFormat } from "react-number-format"
import { useLocation, useNavigate } from "react-router-dom"
import { toast } from "react-toastify"

const GRNFilter = () => {
  const options = { day: "numeric", month: "short", year: "numeric" }
  const [showError, setShowError] = useState(false)
  const [menuOpenIndex, setMenuOpenIndex] = useState(null)
  const [errorMessage, setErrorMessage] = useState("")
  const [loading, setLoading] = useState(false)
  const [page, setPage] = useState(1)
  const [size, setSize] = useState(10)
  const [count, setCount] = useState("")
  const [totalPages, setTotalPages] = useState(0)
  const location = useLocation()
  const [filters, setFilters] = useState({
    po_id: "",
    vendor_internal_id: "",
    delivery_stores: "",
    start_date: null,
    end_date: null,
    delivery_status_code: "",
    invoice_status_code: "",
  })

  const [data, setData] = useState([])
  const [selectedRow, setSelectedRow] = useState(null)
  const [expandedRowIndex, setExpandedRowIndex] = useState(null)
  const [dateRange, setDateRange] = useState(null)
  const navigate = useNavigate()

  const handleChange = e => {
    setFilters({ ...filters, [e.target.name]: e.target.value })
  }

  const deliveryStatusOptions = [
    { value: 1, label: "Not Delivered" },
    { value: 2, label: "Partially Delivered" },
    { value: 3, label: "Completely Delivered" },
  ]

  const invoiceStatusOptions = [
    { value: 1, label: "Not Started" },
    { value: 2, label: "In Process" },
    { value: 3, label: "Finished" },
  ]

  const handleDateRangeChange = value => {
    setDateRange(value)
    setFilters({
      ...filters,
      start_date: value ? dayjs(value[0]).format("YYYY-MM-DD") : "",
      end_date: value ? dayjs(value[1]).format("YYYY-MM-DD") : "",
    })
  }

  const handleShowError = () => {
    setShowError(false)
  }

  const fetchData = async (pageArg, sizeArg, filtersOverride) => {
    const currentPage = pageArg ?? page
    const currentSize = sizeArg ?? size
    const currentFilters = filtersOverride ?? filters

    setLoading(true)
    setShowError(false)

    const token = localStorage.getItem("accessToken")

    if (!token) {
      setErrorMessage("No access token found. Please log in.")
      setShowError(true)
      setLoading(false)
      return
    }

    try {
      const filteredParams = Object.fromEntries(
        Object.entries(currentFilters).filter(([_, value]) => value !== "" && value !== null),
      )

      const response = await axios.get(
        `${process.env.REACT_APP_ENDPOINT_URL}/egrn/v1/filter-grns`,
        {
          params: { ...filteredParams, page: currentPage, size: currentSize },
          headers: { Authorization: `Bearer ${token}` },
        },
      )

      if (response.data.results) {
        setData(response.data.results || [])
        setCount(response.data.count)

        const calculatedTotalPages = Math.ceil(response.data.count / currentSize)
        setTotalPages(calculatedTotalPages)
      } else {
        setErrorMessage("No data available for the requested page.")
        setShowError(true)
      }
    } catch (error) {
      console.error("Error fetching data:", error)
      setErrorMessage(error.response?.data?.message || "An error occurred while fetching data.")
      setShowError(true)
    }

    setLoading(false)
  }

  const handleSearch = () => {
    setPage(1)
    fetchData(1, size)
  }

  const handleResetFilters = () => {
    const resetFilters = {
      po_id: "",
      vendor_internal_id: "",
      delivery_stores: "",
      start_date: null,
      end_date: null,
      delivery_status_code: "",
      invoice_status_code: "",
    }
    setFilters(resetFilters)
    setDateRange(null)
    setPage(1)
    fetchData(1, size, resetFilters)
  }
  const fetchAllFilteredData = async () => {
    const token = localStorage.getItem("accessToken")
    if (!token) {
      toast.error("No access token found. Please log in.")
      return []
    }

    const filteredParams = Object.fromEntries(
      Object.entries(filters).filter(([_, value]) => value !== "" && value !== null),
    )

    try {
      setLoading(true)
      const response = await axios.get(
        `${process.env.REACT_APP_ENDPOINT_URL}/egrn/v1/filter-grns`,
        {
          params: { ...filteredParams, page: 1, size: 10000 }, // Large size to fetch all
          headers: { Authorization: `Bearer ${token}` },
        },
      )
      setLoading(false)
      return response.data.results || []
    } catch (error) {
      setLoading(false)
      console.error("Error fetching data for export:", error)
      toast.error(error?.data?.message || "Failed to fetch data for export.")
      return []
    }
  }

  const exportToCSV = async () => {
    const exportData = await fetchAllFilteredData()
    if (exportData.length === 0) {
      toast.error("No data available to export.")
      return
    }

    const csvData = exportData.flatMap(item => {
      if (!item.grn_line_items || item.grn_line_items.length === 0) {
        return [
          {
            "PO Number": item?.purchase_order?.po_id || "",
            "GRN Number": item.grn_number || "",
            "Vendor Name": item?.purchase_order?.Supplier?.SupplierName?.[0]?.FormattedName || "",
            "Vendor Code": item?.purchase_order?.Supplier?.PartyID || "",
            "Date Created": item.created ? new Date(item.created).toLocaleDateString("en-GB") : "",
            "Store Name": item?.stores?.[0]?.store_name || "",
            "Store ByD Code": item?.stores?.[0]?.byd_cost_center_code || "",
            "Invoice Status": item.invoice_status_text || "",
            "Total Value": item.total_value_received || "",

            // Empty columns for line items
            "Product Name": "",
            "Product Code": "",
            "Qty Received": "",
            "Unit Price": "",
            "Outstanding Qty": "",
            "Value Received": "",
            Tax: "",
          },
        ]
      }

      return item.grn_line_items.map(line => ({
        "PO Number": item?.purchase_order?.po_id || "",
        "GRN Number": item.grn_number || "",
        "Vendor Name": item?.purchase_order?.Supplier?.SupplierName?.[0]?.FormattedName || "",
        "Vendor Code": item?.purchase_order?.Supplier?.PartyID || "",
        "Date Created": item.created ? new Date(item.created).toLocaleDateString("en-GB") : "",
        "Store Name": item?.stores?.[0]?.store_name || "",
        "Store ByD Code": item?.stores?.[0]?.byd_cost_center_code || "",
        "Invoice Status": item.invoice_status_text || "",
        "Delivery Status": item?.purchase_order?.delivery_completed ? "Complete" : "Not Complete",

        // Line item-specific
        "Product Name": line.purchase_order_line_item?.product_name || "",
        "Product Code": line.purchase_order_line_item?.metadata.ProductID,
        "Unit Price": line.purchase_order_line_item?.unit_price || "",
        // "Unit Tax": line.purchase_order_line_item?.metadata?.TaxAmount || "",

        "Quantity Received": line?.quantity_received || "",
        "Net Value Received": line.net_value_received || "",

        "Gross Value Received": line.gross_value_received || "",
        "Total Tax": parseFloat(line.tax_value || 0),
        "Outstanding Qty": line.purchase_order_line_item?.delivery_outstanding_quantity || 0,
      }))
    })

    const csv = Papa.unparse(csvData)
    const blob = new Blob([csv], { type: "text/csv" })
    const url = window.URL.createObjectURL(blob)
    const a = document.createElement("a")
    a.href = url
    a.download = "GRN_History_with_Line_Items.csv"
    document.body.appendChild(a)
    a.click()
    document.body.removeChild(a)
  }

  const handleExport = async () => {
    setLoading(true)
    setShowError(false)

    const token = localStorage.getItem("accessToken")

    if (!token) {
      setErrorMessage("No access token found. Please log in.")
      setShowError(true)
      setLoading(false)
      return
    }

    try {
      const filteredParams = Object.fromEntries(
        Object.entries(filters).filter(([_, value]) => value !== "" && value !== null),
      )

      const queryString = new URLSearchParams(filteredParams).toString()
      const url = `${process.env.REACT_APP_ENDPOINT_URL}/egrn/v1/download-grns${
        queryString ? `?${queryString}` : ""
      }`

      const response = await axios.get(url, {
        headers: { Authorization: `Bearer ${token}` },
      })

      if (response.data.status === "success" && response.data.data?.download_url) {
        const link = document.createElement("a")
        link.href = response.data.data.download_url
        link.setAttribute("download", "")
        document.body.appendChild(link)
        link.click()
        document.body.removeChild(link)
      } else {
        setErrorMessage("Failed to get download URL.")
        setShowError(true)
      }
    } catch (error) {
      console.error("Error exporting data:", error)
      setErrorMessage(error.response?.data?.message || "An error occurred while exporting data.")
      setShowError(true)
    }

    setLoading(false)
  }

  useEffect(() => {
    fetchData(page, size)
  }, [])

  return (
    <div className="border-t border-slate-50 min-h-screen bg-linear-to-br from-blue-50 to-white">
      {loading && <Loader />}
      <Error message={errorMessage} show={showError} handleShow={handleShowError} />

      <Header />
      <div className="flex main-body">
        <div className="sidebar hidden md:block">
          <Sidebar />
        </div>
        <div className="content md:w-[86%] w-full md:ml-[14%] p-3">
          <div className="text-base rounded-lg font-semibold mb-4 bg-white  py-3 px-6 text-blue-800 flex flex-col md:flex-row justify-between items-center gap-4 md:gap-0">
            <div>GRN History</div>
            <button
              onClick={handleExport}
              className="flex items-center gap-2 bg-green-600 hover:bg-green-700 text-white font-semibold rounded-lg px-4 py-2  transition-all duration-150 w-full md:w-auto"
            >
              <Download className="h-5" /> Export as CSV
            </button>
          </div>
          <div className="rounded-xl bg-white">
            <div className="w-full px-6 pt-6 pb-2 ">
              <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                <DateRangePicker
                  format="dd/MM/yyyy"
                  placeholder="Select Date Range"
                  value={dateRange}
                  onChange={handleDateRangeChange}
                  showOneCalendar
                  className="w-full border border-gray-300 rounded-md focus:border-blue-500 focus:ring-2 focus:ring-blue-300"
                />
                <input
                  type="text"
                  name="po_id"
                  value={filters.po_id}
                  onChange={handleChange}
                  placeholder="Po id"
                  className="border-gray-300 py-2 px-4 border rounded-md focus:border-blue-500 focus:ring-2 focus:ring-blue-300 w-full"
                />
                <input
                  type="text"
                  name="vendor_internal_id"
                  value={filters.vendor_internal_id}
                  onChange={handleChange}
                  placeholder="Vendor internal id"
                  className="border-gray-300 py-2 px-4 border rounded-md focus:border-blue-500 focus:ring-2 focus:ring-blue-300 w-full"
                />
                <input
                  type="text"
                  name="delivery_stores"
                  value={filters.delivery_stores}
                  onChange={handleChange}
                  placeholder="Delivery stores"
                  className="border-gray-300 py-2 px-4 border rounded-md focus:border-blue-500 focus:ring-2 focus:ring-blue-300 w-full"
                />
                <select
                  name="delivery_status_code"
                  value={filters.delivery_status_code}
                  onChange={handleChange}
                  className="border-gray-300 py-2 px-4 bg-white border rounded-md focus:border-blue-500 focus:ring-2 focus:ring-blue-300 w-full"
                >
                  <option value="" className="font-poppins">
                    Select Delivery Status
                  </option>
                  {deliveryStatusOptions.map(option => (
                    <option key={option.value} value={option.value} className="font-poppins">
                      {option.label}
                    </option>
                  ))}
                </select>
                <select
                  name="invoice_status_code"
                  value={filters.invoice_status_code}
                  onChange={handleChange}
                  className="border-gray-300 py-2 px-4 bg-white border rounded-md focus:border-blue-500 focus:ring-2 focus:ring-blue-300 w-full"
                >
                  <option value="" className="font-poppins">
                    Select Invoice Status
                  </option>
                  {invoiceStatusOptions.map(option => (
                    <option key={option.value} value={option.value} className="font-poppins">
                      {option.label}
                    </option>
                  ))}
                </select>
                <button
                  onClick={handleSearch}
                  className="p-2 bg-blue-800 text-white rounded-md hover:bg-blue-900 w-full"
                >
                  Search
                </button>
                <button
                  onClick={handleResetFilters}
                  className="p-2 bg-white border text-gray-700 rounded-md hover:bg-gray-50 w-full flex items-center justify-center gap-2"
                >
                  <RotateCcw className="h-4 w-4" /> Reset Filters
                </button>
              </div>
            </div>

            {data.length > 0 ? (
              <div className="overflow-x-auto m-6  rounded-lg  min-w-[900px] border ">
                <table className="w-full bg-white">
                  <thead>
                    <tr className="bg-blue-800 text-white font-semibold">
                      <td className="pl-4 py-3"> </td>
                      <td className="p-3 text-left">SN</td>
                      <td className="p-3 text-left">PO Number</td>
                      <td className="p-3 text-left">GRN Number</td>
                      <td className="p-3 text-left">Vendor ID</td>
                      <td className="p-3 text-left">Date Created</td>
                      <td className="p-3 text-left">Store Code</td>
                      <td className="p-3 text-left">Delivery Status</td>
                      <td className="p-3 text-left">Invoice Status</td>
                      <td className="text-right pr-6">Total Value</td>
                      <td className="p-3 text-center">Actions</td>
                    </tr>
                  </thead>
                  <tbody>
                    {data.map((item, index) => (
                      <React.Fragment key={item.grn_number}>
                        <tr
                          className={`border-t border-gray-300 transition-all duration-200 ${
                            expandedRowIndex === index
                              ? " border-b border-gray-200"
                              : "hover:bg-gray-50 bg-white"
                          }`}
                        >
                          <td className="pl-4 py-3">
                            <button
                              onClick={() =>
                                setExpandedRowIndex(expandedRowIndex === index ? null : index)
                              }
                              className="text-gray-600 hover:text-black"
                            >
                              {expandedRowIndex === index ? (
                                <ChevronDown size={18} />
                              ) : (
                                <ChevronRight size={18} />
                              )}
                            </button>
                          </td>
                          <td className="p-3">
                            {page === 1 ? page + index : size * page - size + 1 + index}
                          </td>
                          <td className="p-3">{item?.purchase_order?.po_id}</td>
                          <td className="p-3">{item.grn_number}</td>
                          <td className="p-3">{item?.purchase_order?.Supplier?.PartyID}</td>
                          <td className="p-3">
                            {new Date(item.created).toLocaleDateString("en-GB", options)}
                          </td>
                          <td className="p-3">{item?.stores?.[0]?.byd_cost_center_code}</td>
                          <td className="p-3">
                            <div className="w-fit px-3 py-1 rounded-md text-xs font-medium bg-blue-100 text-blue-700 border border-blue-500">
                              {item?.purchase_order?.delivery_status_text}
                            </div>
                          </td>
                          <td className="p-3">
                            <div
                              className={`w-fit px-3 py-1 rounded-md text-xs font-medium ${
                                item?.invoice_status_text === "Finished"
                                  ? "bg-green-100 text-green-700 border border-green-500"
                                  : "bg-gray-100 text-gray-700 border border-gray-400"
                              }`}
                            >
                              {item?.invoice_status_text}
                            </div>
                          </td>
                          <td className="text-right pr-6 whitespace-nowrap">
                            ₦
                            <NumericFormat
                              value={item?.total_value_received}
                              displayType="text"
                              thousandSeparator
                              decimalSeparator="."
                              decimalScale={2}
                              fixedDecimalScale
                            />
                          </td>
                          <td className="p-3 text-center relative">
                            <button
                              onClick={() =>
                                setMenuOpenIndex(index === menuOpenIndex ? null : index)
                              }
                              className="text-gray-700 hover:text-blue-500"
                            >
                              <MoreHorizontal className="h-5 w-5" />
                            </button>
                            {menuOpenIndex === index && (
                              <div className="absolute right-0 mt-2 w-40 bg-white border border-gray-300 rounded-md shadow-lg z-10">
                                <button
                                  className="w-full px-4 py-2 text-left text-gray-600 hover:bg-gray-100 text-sm"
                                  onClick={() => {
                                    setSelectedRow(item)
                                    setMenuOpenIndex(null)
                                  }}
                                >
                                  View Details
                                </button>
                                <button
                                  className="w-full px-4 py-2 text-left text-gray-600 hover:bg-gray-100 text-sm"
                                  onClick={() => {
                                    localStorage.setItem("PostResponse", JSON.stringify(item))
                                    navigate("/grn", { state: { history: true } })
                                    setMenuOpenIndex(null)
                                  }}
                                >
                                  View GRN
                                </button>
                              </div>
                            )}
                          </td>
                        </tr>

                        {expandedRowIndex === index && (
                          <tr>
                            <td colSpan={12}>
                              <div className="flex justify-center py-4">
                                <table className="text-sm w-[90%] border border-gray-200 rounded-lg shadow-sm">
                                  <thead className="bg-white text-gray-700 font-medium">
                                    <tr>
                                      <td className="p-3">Product Name</td>
                                      <td className="p-3">Product Code</td>
                                      <td className="p-3">UoM</td>
                                      <td className="text-right pr-6">Qty Received</td>
                                      <td className="text-right pr-12">Outstanding Qty</td>
                                      <td className="text-right pr-12">Unit Price</td>
                                      <td className="text-right pr-12">Value Received</td>
                                      <td className="text-right pr-4">Tax</td>
                                    </tr>
                                  </thead>
                                  <tbody>
                                    {item.grn_line_items.map((line, idx) => (
                                      <tr
                                        key={idx}
                                        className={`$${idx % 2 === 0 ? "bg-white" : "bg-white"} border-t border-slate-200`}
                                      >
                                        <td className="p-3">
                                          {line.purchase_order_line_item.product_name}
                                        </td>
                                        <td className="p-3">
                                          {line.purchase_order_line_item.metadata.ProductID}
                                        </td>
                                        <td className="p-3">
                                          {
                                            line.purchase_order_line_item.metadata
                                              .ListUnitPriceBaseUnitCode
                                          }
                                        </td>
                                        <td className="text-right pr-6">
                                          <NumericFormat
                                            value={line.quantity_received}
                                            displayType="text"
                                            thousandSeparator
                                            decimalSeparator="."
                                            decimalScale={2}
                                            fixedDecimalScale
                                          />
                                        </td>
                                        <td className="text-right pr-12">
                                          <NumericFormat
                                            value={
                                              line.purchase_order_line_item
                                                .delivery_outstanding_quantity
                                            }
                                            displayType="text"
                                            thousandSeparator
                                            decimalSeparator="."
                                            decimalScale={2}
                                            fixedDecimalScale
                                          />
                                        </td>
                                        <td className="text-right pr-12">
                                          ₦
                                          <NumericFormat
                                            value={line.purchase_order_line_item.unit_price}
                                            displayType="text"
                                            thousandSeparator
                                            decimalSeparator="."
                                            decimalScale={2}
                                            fixedDecimalScale
                                          />
                                        </td>
                                        <td className="text-right pr-12">
                                          ₦
                                          <NumericFormat
                                            value={line.gross_value_received}
                                            displayType="text"
                                            thousandSeparator
                                            decimalSeparator="."
                                            decimalScale={2}
                                            fixedDecimalScale
                                          />
                                        </td>
                                        <td className="text-right pr-4">
                                          ₦
                                          <NumericFormat
                                            value={parseFloat(line?.tax_value)}
                                            displayType="text"
                                            thousandSeparator
                                            decimalSeparator="."
                                            decimalScale={2}
                                            fixedDecimalScale
                                          />
                                        </td>
                                      </tr>
                                    ))}
                                  </tbody>
                                </table>
                              </div>
                            </td>
                          </tr>
                        )}
                      </React.Fragment>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : (
              <div className="text-center text-gray-500 py-8">No data found.</div>
            )}

            <div className="px-4 pb-6">
              <Pagination
                totalPages={totalPages}
                entriesPerPage={size}
                totalEntries={count}
                currentPage={page}
                onPageChange={newPage => {
                  setPage(newPage)
                  fetchData(newPage, size)
                }}
                onPageSizeChange={newSize => {
                  setSize(newSize)
                  setPage(1)
                  fetchData(1, newSize)
                }}
              />
            </div>

            {selectedRow && (
              <div
                className="fixed inset-0 bg-black bg-opacity-50 right-1 flex justify-end z-50"
                onClick={() => setSelectedRow(null)}
              >
                <div
                  className="bg-white h-screen overflow-auto w-full md:w-[30%] shadow-lg overflow-y-auto"
                  onClick={e => e.stopPropagation()}
                >
                  <div className="flex justify-between items-center border-b p-4">
                    <h2 className="text-lg font-medium">Full Details</h2>
                    <button
                      onClick={() => setSelectedRow(null)}
                      className="text-gray-500 hover:text-gray-700"
                    >
                      <X size={20} className="border rounded-full" />
                    </button>
                  </div>
                  <div className="px-4">
                    {(() => {
                      const details = [
                        { label: "PO Number", value: selectedRow?.purchase_order?.po_id },
                        { label: "GRN Number", value: selectedRow?.grn_number },
                        {
                          label: "Vendor Name",
                          value:
                            selectedRow?.purchase_order?.Supplier?.SupplierName?.[0]?.FormattedName,
                        },
                        {
                          label: "Vendor Code",
                          value: selectedRow?.purchase_order?.Supplier?.PartyID,
                        },
                        { label: "Store Name", value: selectedRow?.stores?.[0]?.store_name },
                        {
                          label: "Store Code",
                          value: selectedRow?.stores?.[0]?.byd_cost_center_code,
                        },
                        {
                          label: "Invoice Status",
                          value: selectedRow?.invoice_status_text,
                          status: true,
                        },
                        {
                          label: "Total Value",
                          value: selectedRow?.total_value_received,
                          currency: true,
                        },
                      ]
                      return details.map((item, index) => (
                        <div
                          key={index}
                          className="flex flex-col sm:flex-row mt-4 text-sm justify-between gap-1 sm:gap-0"
                        >
                          <div className="sm:w-[50%] text-gray-900 font-medium">{item.label}</div>
                          <div className="text-gray-500 sm:w-[50%] text-right break-words">
                            {item.status ? (
                              <div
                                className={`flex items-center gap-1 ${selectedRow?.invoice_status_text ? "text-green-600" : "text-gray-700"}`}
                              >
                                <div
                                  className={`h-2 w-2 rounded-full ${selectedRow?.invoice_status_text ? "bg-green-600" : "bg-gray-400"}`}
                                ></div>
                                {selectedRow?.invoice_status_text}
                              </div>
                            ) : item.currency ? (
                              <NumericFormat
                                value={item.value}
                                displayType="text"
                                thousandSeparator
                                decimalSeparator="."
                                decimalScale={2}
                                fixedDecimalScale
                                prefix="₦"
                              />
                            ) : (
                              item.value || "N/A"
                            )}
                          </div>
                        </div>
                      ))
                    })()}
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  )
}

export default GRNFilter
